"""Current v30f report only; preserves the interrupted v29c campaign separately."""
import json,re
from pathlib import Path
H=Path(__file__).resolve().parent
def read(p,default=None):return json.loads(p.read_text()) if p.exists() else default
rows=read(H/'v30_manifest.json',read(H/'v30_singletons.json',[]))
seen={r['stem'] for r in rows}
for r in read(H/'v30_mzinit.json',[]):
    if r['stem'] not in seen:rows.append(dict(stem=r['stem'],edits=['extra reset→measure '+str(r['edit']['q'])]));seen.add(r['stem'])
for r in read(H/'v30_readout.json',[])+read(H/'v30_extra_combinations.json',[])+read(H/'v30_phase.json',[])+read(H/'v30_extra_edges.json',[])+read(H/'v30_frame_init.json',[])+read(H/'v30_frame_group.json',[])+read(H/'v30_measurement_basis.json',[])+read(H/'v30_unfold_family.json',[]):
    if r['stem'] not in seen:
        md=read(H/(r['stem']+'.json'),{})
        rows.append(dict(stem=r['stem'],edits=r.get('edits',md.get('comp29_edits',[r['stem']])),build_error=r.get('error')));seen.add(r['stem'])
for name in ['f_timing_best','f_timing_best_r0','f_timing_best_r1','f_timing_best_r2','f_timing_refined']:
    if (H/(name+'.qasm')).exists() and name not in seen:rows.append(dict(stem=name,edits=['fresh exact-loss timing feedback on f_c0df']))
for name in ['f_remove_edge_17_16','f_remove_edge_19_25']:
    if (H/(name+'.qasm')).exists() and name not in seen:rows.append(dict(stem=name,edits=[name.removeprefix('f_')]))
out=[]
for r in rows:
    n=r['stem'];z=dict(r)
    for key,suffix in [('screen','screen'),('exact','exact'),('gate','gate'),('allorders','allorders')]:z[key]=read(H/(n+'.'+suffix+'.json'),{})
    if not z['exact']:
        eq=read(H/(n+'.exact_equivalent.json'),{})
        if eq.get('reference_unchanged_cli'):z['exact']=eq
    mc={};p=H/(n+'.mc.log')
    if p.exists():
        text=p.read_text();m=re.search(r' mean (\S+)',text)
        if m:mc['mean']=float(m[1])
        mc['seeds']={int(m[1]):dict(loss=float(m[2]),acceptance=float(m[3])) for m in re.finditer(r' (0|1000|2000) (\S+) ± .* acc (\S+)',text)}
    z['mc']=mc;out.append(z)
eligible=lambda r:r['gate'].get('passed') and r['screen'].get('exp_minus_A1',0)>=.5002
ranked=sorted([r for r in out if eligible(r) and r['allorders'].get('validated')],key=lambda r:r['allorders']['loss'])
mc_ranked=sorted([r for r in out if eligible(r) and len(r['mc'].get('seeds',{}))==3],key=lambda r:r['mc']['mean'])
available={r['stem']:r for r in ranked+mc_ranked}
best=min(available.values(),key=lambda r:r['allorders'].get('loss',r['mc'].get('mean',1))) if available else None
delivery=read(H/'best.verification.json')
headline=(f"**Verified delivery:** [best.qasm](best.qasm) / [best.json](best.json) = `{delivery['stem']}`: **all-orders {delivery['allorders']['loss']:.12g} (−{delivery['improvement_percent_vs_v30f']:.6g}% vs v30f), acceptance {delivery['allorders']['acceptance']:.12g}, 194 CX, R48, FAST**. Independent unchanged exact2 confirms {delivery['exact']['total']:.6g}; three-seed 1e8 mean is {delivery['mc']['mean']:.8g}, seed-0 acceptance {delivery['mc']['seeds']['0']['acceptance']:.5f}. Actual 1e6 judge time: {delivery['gate']['judge_seconds']:.2f} s. The per-combination reference sweep is still running; this delivery’s own checks are complete.")
