for r in sorted(out,key=lambda r:r['screen'].get('total',1)):
    s,e,g,a,mc=(r[k] for k in ['screen','exact','gate','allorders','mc']);sp=g.get('speed',{})
    judge=('PASS' if g['passed'] else 'FAIL')+f" / {g['acceptance']:.6f}" if 'passed' in g else g.get('error','pending')
