    ref='completed' if e.get('unchanged_cli') else 'proved equivalent CLI' if e.get('reference_unchanged_cli') else 'inherited baseline' if r['stem']=='f_base' else 'pending'
    if r.get('build_error'):judge='NOISELESS FAIL';ref='model rejected'
    er=read(H/(r['stem']+'.exact_error.json'),{})
    if er and not e:ref='reference scope rejected'
    lines.append('| `%s` | %s | %s | %s | %s | %s | %s | %s | %s |'%(r['stem'],' + '.join(x if isinstance(x,str) else json.dumps(x,sort_keys=True) for x in r['edits']) or 'v30f control',fmt(s.get('total')),fmt(s.get('exp_minus_A1')),ref,judge,speed,fmt(a.get('loss')),fmt(mc.get('mean'))))
